-- Function: public.fn_resolve_teacher_id
-- Backup generated on 2026-10-25 20:33:47

CREATE OR REPLACE FUNCTION public.fn_resolve_teacher_id(p_tenant_id uuid, p_teacher_or_user_id uuid, p_classroom_id uuid DEFAULT NULL::uuid)  RETURNS uuid  LANGUAGE plpgsql AS $function$ DECLARE     v_found_id UUID;     v_new_teacher_id UUID; BEGIN     -- 1. Direct teacher ID     SELECT t.id INTO v_found_id     FROM teachers t     WHERE t.id = p_teacher_or_user_id AND t.tenant_id = p_tenant_id     LIMIT 1;      IF v_found_id IS NOT NULL THEN         RETURN v_found_id;     END IF;      -- 2. User ID linked to teacher     SELECT t.id INTO v_found_id     FROM teachers t     WHERE t.user_id = p_teacher_or_user_id AND t.tenant_id = p_tenant_id     LIMIT 1;      IF v_found_id IS NOT NULL THEN         RETURN v_found_id;     END IF;      -- 3. Classroom teacher     IF p_classroom_id IS NOT NULL THEN         SELECT t.id INTO v_found_id         FROM classroom_teachers ct         JOIN teachers t ON ct.user_id = t.user_id AND ct.tenant_id = t.tenant_id         WHERE ct.classroom_id = p_classroom_id AND ct.tenant_id = p_tenant_id         ORDER BY ct.is_primary DESC         LIMIT 1;          IF v_found_id IS NOT NULL THEN             RETURN v_found_id;         END IF;     END IF;      -- 4. Any active teacher     SELECT t.id INTO v_found_id     FROM teachers t     WHERE t.tenant_id = p_tenant_id AND t.status != 'Inactive'     LIMIT 1;      IF v_found_id IS NOT NULL THEN         RETURN v_found_id;     END IF;      -- 5. Auto-create if user exists     v_new_teacher_id := gen_random_uuid();     INSERT INTO teachers (         id, tenant_id, user_id, first_name, last_name, display_name, status, created_at, updated_at     )     SELECT v_new_teacher_id, p_tenant_id, u.id, COALESCE(u.first_name, 'Teacher'), COALESCE(u.last_name, 'Staff'), COALESCE(u.display_name, 'Lead Educator'), 'Active', NOW(), NOW()     FROM users u     WHERE u.id = p_teacher_or_user_id AND u.tenant_id = p_tenant_id     ON CONFLICT (id) DO NOTHING;      IF FOUND THEN         RETURN v_new_teacher_id;     END IF;      RETURN p_teacher_or_user_id; END; $function$ ;
